<?php if(!defined('APP_ENTRY'))exit; $table='staff_accounts';$entity='staff account';$heading='Staff accounts';$fields=['name'=>['label'=>'Full name','max'=>100],'username'=>['label'=>'Username','max'=>50],'role'=>['label'=>'Role','options'=>['teacher'=>'Teacher','admin'=>'Administrator']],'active'=>['label'=>'Account status','options'=>[1=>'Active',0=>'Inactive']],'password'=>['label'=>'Password (leave blank to keep existing)','type'=>'password']];
